const puppeteer = require('puppeteer')
const { author } = require('../../config')

async function fbdl(url) {
  if (!url) throw new Error('URL requerida')

  const browser = await puppeteer.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-blink-features=AutomationControlled'
    ]
  })

  const page = await browser.newPage()

  await page.setUserAgent(
    'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36'
  )

  await page.goto('https://fdownloader.net/en', {
    waitUntil: 'domcontentloaded'
  })

  await page.waitForFunction(() => {
    return document.body.innerText.includes('Facebook Video Downloader')
  }, { timeout: 60000 })

  const inputSelector = await page.evaluate(() => {
    const input =
      document.querySelector('#search-form-input') ||
      document.querySelector('input[type="text"]')
    return input ? (input.id ? `#${input.id}` : 'input[type="text"]') : null
  })

  if (!inputSelector) {
    throw new Error('No se encontró el input (Cloudflare o cambio de web)')
  }

  await page.type(inputSelector, url)

  const btnSelector = await page.evaluate(() => {
    const btn =
      document.querySelector('#search-form-button') ||
      document.querySelector('button')
    return btn ? (btn.id ? `#${btn.id}` : 'button') : null
  })

  if (!btnSelector) {
    throw new Error('No se encontró el botón')
  }

  await page.click(btnSelector)

  // Esperar resultados
  await page.waitForSelector('table tbody tr', { timeout: 60000 })

  const result = await page.evaluate(() => {
    const clean = (txt) => txt?.toLowerCase() || ''

    let videos = []
    let thumbnail = document.querySelector('.thumbnail img')?.src || null
    let duration = document.querySelector('.content p')?.innerText || null

    document.querySelectorAll('table tbody tr').forEach(el => {
      const quality = clean(el.innerText)
      let link = el.querySelector('a')?.href

      if (link) {
        link = link.replace(/&amp;/g, '&')
        videos.push({ quality, url: link })
      }
    })

    let audio =
      document.querySelector('#audioUrl')?.value?.replace(/&amp;/g, '&') || null

    return {
      thumbnail,
      duration,
      videos,
      audio
    }
  })

  await browser.close()

  if (!result.videos.length) {
    throw new Error('No se encontraron videos')
  }

  const HD =
    result.videos.find(v => v.quality.includes('hd') || v.quality.includes('720'))?.url || null

  const SD =
    result.videos.find(v => v.quality.includes('sd') || v.quality.includes('360'))?.url || null

  return {
    author,
    thumb: result.thumbnail,
    duration: result.duration,
    HD,
    SD,
    audio: result.audio
  }
}

module.exports = { fbdl }